def k7_chain_l1__ref(n):
    qc = QuantumCircuit(n)
    for i in range(0, n):
        qc.ry(math.pi / 2, i)
        qc.rz(math.pi / 4, i)
    for i in range(0, n - 1):
        qc.cx(i, i + 1)
    return qc


