    qc = QuantumCircuit(n)
    for j in range(1, n + 1):
        qc.ry(math.pi / 2, j - 1)
        qc.rz(math.pi / 4, j - 1)
    for j in range(1, n):
        qc.cx(j - 1, j)
    return qc


