def k7_ring_l1__ref(n):
    qc = QuantumCircuit(n)
    for i in range(0, n):
        qc.ry(math.pi / 2, i)
        qc.rz(math.pi / 4, i)
    for i in range(0, n - 1):
        qc.cx(i, i + 1)
    qc.cx(n - 1, 0)
    return qc


def k7_ring_l1__st_shift(n):
    qc = QuantumCircuit(n)
    for j in range(1, n + 1):
        qc.ry(math.pi / 2, j - 1)
        qc.rz(math.pi / 4, j - 1)
    for j in range(1, n):
        qc.cx(j - 1, j)
    qc.cx(n - 1, 0)
    return qc


def k7_ring_l1__st_helper(n):
    qc = QuantumCircuit(n)
    k7_ring_l1__st_helper_layers(qc, n)
    return qc


